INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13201, 'តើលក្ខណៈណាដែលបញ្ជាក់ថាស្វ៊ីតនៃចំនួនពិត \( (a_n) \) ជា «ស្វ៊ីតនព្វន្ត»?', NULL, '["តួនីមួយៗស្មើនឹងតួមុនបន្ទាប់គុណនឹងចំនួនថេរ \\( q \\)", "តួនីមួយៗ (ក្រៅពីតួទី ១) ស្មើនឹងតួមុនបន្ទាប់បូកនឹងចំនួនថេរ \\( d \\)", "ផលចែករវាងពីរតួតគ្នាជាចំនួនថេរជានិច្ច", "ផលបូកនៃពីរតួតគ្នាជាចំនួនថេរជានិច្ច"]', 1, NULL, 2, 'mcq', 'តាមនិយមន័យ ស្វ៊ីតនព្វន្តគឺជាស្វ៊ីតដែលតួនីមួយៗ (ក្រៅពីតួទី ១) ស្មើនឹងតួមុនបន្ទាប់បូកចំនួនថេរ \( d \) ហៅថាផលសងរួម (\( a_{n+1} = a_n + d \))។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13202, 'រកផលសងរួម \( d \) នៃស្វ៊ីតនព្វន្ត \( 4, 15, 26, 37, \dots \)៖', NULL, '["\\( d = 9 \\)", "\\( d = -11 \\)", "\\( d = 11 \\)", "\\( d = 15 \\)"]', 2, NULL, 2, 'mcq', 'ផលសងរួម \( d = a_2 - a_1 = 15 - 4 = 11 \)។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13203, 'រកផលសងរួម \( d \) នៃស្វ៊ីតនព្វន្ត \( 5, 1, -3, -7, -11, \dots \)៖', NULL, '["\\( d = 4 \\)", "\\( d = -5 \\)", "\\( d = -4 \\)", "\\( d = -6 \\)"]', 2, NULL, 2, 'mcq', 'ផលសងរួម \( d = a_2 - a_1 = 1 - 5 = -4 \)។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13204, 'តើរូបមន្តទូទៅសម្រាប់គណនាតួទី \( n \) នៃស្វ៊ីតនព្វន្តដែលមានតួទីមួយ \( a_1 \) និងផលសងរួម \( d \) គឺជាអ្វី?', NULL, '["\\( a_n = a_1 + (n - 1)d \\)", "\\( a_n = a_1 + nd \\)", "\\( a_n = a_1 \\times d^{n-1} \\)", "\\( a_n = \\dfrac{a_1 + d}{n} \\)"]', 0, NULL, 2, 'mcq', 'រូបមន្តតួទី \( n \) នៃស្វ៊ីតនព្វន្តគឺ \( a_n = a_1 + (n - 1)d \)។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13205, 'គេមានស្វ៊ីតនព្វន្តដែលមានតួទីមួយ \( a_1 = 2 \) និង \( a_2 = 9 \)។ គណនាតួទី \( a_5 \)៖', NULL, '["\\( 30 \\)", "\\( 28 \\)", "\\( 35 \\)", "\\( 37 \\)"]', 0, NULL, 2, 'mcq', 'ផលសងរួម \( d = 9 - 2 = 7 \)។ នាំឱ្យ \( a_5 = a_1 + 4d = 2 + 4(7) = 30 \)។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13206, 'គេឱ្យស្វ៊ីតនព្វន្តមាន \( a_1 = 3 \) និង \( a_{n+1} = a_n - \dfrac{1}{4} \)។ រកតួទី \( a_2 \)៖', NULL, '["\\( \\dfrac{11}{4} \\)", "\\( \\dfrac{13}{4} \\)", "\\( \\dfrac{7}{4} \\)", "\\( \\dfrac{5}{2} \\)"]', 0, NULL, 2, 'mcq', '\( a_2 = a_1 - \dfrac{1}{4} = 3 - \dfrac{1}{4} = \dfrac{11}{4} \)។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13207, 'តើរូបមន្តផលបូក \( n \) តួដំបូង \( S_n \) នៃស្វ៊ីតនព្វន្តដោយស្គាល់តួទីមួយ \( a_1 \) និងតួទី \( a_n \) គឺ៖', NULL, '["\\( S_n = n(a_1 + a_n) \\)", "\\( S_n = \\dfrac{n}{2}(a_1 + a_n) \\)", "\\( S_n = \\dfrac{a_1 + a_n}{2} \\)", "\\( S_n = \\dfrac{n}{2}(a_1 - a_n) \\)"]', 1, NULL, 2, 'mcq', 'រូបមន្តផលបូក \( n \) តួដំបូងគឺ \( S_n = \dfrac{n}{2}(a_1 + a_n) \) ឬ \( S_n = \dfrac{n[2a_1 + (n - 1)d]}{2} \)។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g11-b62b5d3194.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13208, 'ក្នុងស្វ៊ីតនព្វន្តមួយ ប្រសិនបើគេដឹងថាផលបូកតួចុង \( a_1 + a_6 = 20 \)។ តើផលបូកតួស្មើចម្ងាយពីតួចុង \( a_2 + a_5 \) ស្មើនឹងប៉ុន្មាន?', 'g11-b62b5d3194.svg', '["\\( 10 \\)", "\\( 20 \\)", "\\( 40 \\)", "\\( 25 \\)"]', 1, NULL, 2, 'mcq', 'តាមលក្ខណៈស្វ៊ីតនព្វន្ត ផលបូកតួស្មើចម្ងាយពីតួចុងស្មើគ្នានឹងផលបូកតួចុង៖ \( a_1 + a_6 = a_2 + a_5 = a_3 + a_4 = 20 \)។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13209, 'ក្នុងចំណោមស្វ៊ីតខាងក្រោម តើស្វ៊ីតណាជាស្វ៊ីតនព្វន្ត?', NULL, '["\\( a_n = 3n^2 + 1 \\)", "\\( a_n = -7 + 3n \\)", "\\( a_n = 2^n \\)", "\\( a_n = \\dfrac{1}{n} \\)"]', 1, NULL, 2, 'mcq', 'កន្សោមដឺក្រេទី ១ ធៀបនឹង \( n \) (\( a_n = An + B \)) ជាស្វ៊ីតនព្វន្តដែលមានផលសងរួម \( d = A = 3 \)។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13210, 'ស្វ៊ីត \( (a_n) \) កំណត់ដោយ \( a_n = 13 + 6(n - 1) \)។ រកតួទីមួយ \( a_1 \) និងផលសងរួម \( d \)៖', NULL, '["\\( a_1 = 6, \\, d = 13 \\)", "\\( a_1 = 19, \\, d = 6 \\)", "\\( a_1 = 13, \\, d = 6 \\)", "\\( a_1 = 13, \\, d = -6 \\)"]', 2, NULL, 2, 'mcq', 'ចំពោះ \( n = 1 \implies a_1 = 13 + 0 = 13 \) និងផលសងរួមគឺជាមេគុណនៃ \( n - 1 \) គឺ \( d = 6 \)។', 'ស្វ៊ីតនព្វន្ត', 'easy', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13211, 'គេមានស្វ៊ីតនព្វន្ត \( 2, 8, 14, 20, \dots \)។ គណនាតួទី \( 20 \) (\( a_{20} \))៖', NULL, '["\\( 116 \\)", "\\( 120 \\)", "\\( 114 \\)", "\\( 122 \\)"]', 0, NULL, 3, 'mcq', '\( a_1 = 2, \, d = 8 - 2 = 6 \)។ នាំឱ្យ \( a_{20} = 2 + (20 - 1) \times 6 = 2 + 114 = 116 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13212, 'គេមានស្វ៊ីតនព្វន្ត \( 2, 8, 14, 20, \dots \)។ តើចំនួន \( 236 \) ជាតួទីប៉ុន្មាននៃស្វ៊ីត?', NULL, '["តួទី 40", "តួទី 38", "តួទី 39", "តួទី 41"]', 0, NULL, 3, 'mcq', '\( a_n = 2 + (n - 1)6 = 236 \implies 6(n - 1) = 234 \implies n - 1 = 39 \implies n = 40 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13213, 'កំណត់ចំនួនតួនៃស្វ៊ីតនព្វន្ត \( 18, 13, 8, \dots, -102 \)៖', NULL, '["24 តួ", "25 តួ", "26 តួ", "23 តួ"]', 1, NULL, 3, 'mcq', '\( a_1 = 18, \, d = -5 \)។ \( 18 + (n - 1)(-5) = -102 \implies -5(n - 1) = -120 \implies n - 1 = 24 \implies n = 25 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13214, 'កំណត់ចំនួនតួនៃស្វ៊ីតនព្វន្ត \( -9, -4, 1, \dots, 171 \)៖', NULL, '["37 តួ", "36 តួ", "38 តួ", "35 តួ"]', 0, NULL, 3, 'mcq', '\( a_1 = -9, \, d = 5 \)។ \( -9 + 5(n - 1) = 171 \implies 5(n - 1) = 180 \implies n - 1 = 36 \implies n = 37 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13215, 'គេឱ្យ \( (a_n) \) ជាស្វ៊ីតនព្វន្តដែលមាន \( a_{35} = 9 \) និង \( a_{45} = 17 \)។ គណនា \( a_{40} \)៖', NULL, '["\\( 12 \\)", "\\( 13 \\)", "\\( 14 \\)", "\\( 15 \\)"]', 1, NULL, 3, 'mcq', 'ដោយ \( 40 \) ជាចំណុចកណ្តាលរវាង \( 35 \) និង \( 45 \) នាំឱ្យ \( a_{40} = \dfrac{a_{35} + a_{45}}{2} = \dfrac{9 + 17}{2} = 13 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13216, 'គេឱ្យស្វ៊ីតនព្វន្ត \( (a_n) \) មាន \( a_7 = \dfrac{7}{2} \) និង \( a_{13} = \dfrac{13}{2} \)។ រកតួទីមួយ \( a_1 \)៖', NULL, '["\\( 1 \\)", "\\( \\dfrac{3}{2} \\)", "\\( 0 \\)", "\\( \\dfrac{1}{2} \\)"]', 3, NULL, 3, 'mcq', '\( a_{13} - a_7 = 6d \implies \dfrac{13}{2} - \dfrac{7}{2} = 3 \implies 6d = 3 \implies d = \dfrac{1}{2} \)។ នាំឱ្យ \( a_1 = a_7 - 6d = \dfrac{7}{2} - 3 = \dfrac{1}{2} \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13217, 'គណនាផលបូកចំនួនគូ \( 2 + 4 + 6 + \dots + 146 \)៖', NULL, '["\\( 5402 \\)", "\\( 5256 \\)", "\\( 5476 \\)", "\\( 5366 \\)"]', 3, NULL, 3, 'mcq', '\( a_1 = 2, \, d = 2, \, a_n = 146 \implies n = 73 \)។ ផលបូក \( S_{73} = \dfrac{73}{2}(2 + 146) = 73 \times 74 = 5402 \)។ (ជម្រើសកែតម្រូវ: 5402)', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13218, 'គណនាផលបូក \( 25 \) តួដំបូងនៃស្វ៊ីតនព្វន្ត \( 2, 7, 12, 17, \dots \)៖', NULL, '["\\( 1500 \\)", "\\( 1600 \\)", "\\( 1550 \\)", "\\( 1525 \\)"]', 2, NULL, 3, 'mcq', '\( a_1 = 2, \, d = 5 \)។ \( S_{25} = \dfrac{25}{2}[2(2) + 24(5)] = \dfrac{25}{2}[4 + 120] = 25 \times 62 = 1550 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13219, 'គណនាផលបូក \( (-6) + (-1) + 4 + 9 + \dots + 64 \)៖', NULL, '["\\( 420 \\)", "\\( 450 \\)", "\\( 435 \\)", "\\( 465 \\)"]', 2, NULL, 3, 'mcq', '\( a_1 = -6, \, d = 5 \)។ \( -6 + 5(n - 1) = 64 \implies 5(n - 1) = 70 \implies n = 15 \)។ \( S_{15} = \dfrac{15}{2}(-6 + 64) = 15 \times 29 = 435 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13220, 'គណនាផលបូកនៃស្វ៊ីតចុះ \( 100 + 95 + 90 + 85 + \dots + (-20) \)៖', NULL, '["\\( 960 \\)", "\\( 1050 \\)", "\\( 1000 \\)", "\\( 900 \\)"]', 2, NULL, 3, 'mcq', '\( a_1 = 100, \, d = -5 \)។ \( 100 - 5(n - 1) = -20 \implies 5(n - 1) = 120 \implies n = 25 \)។ \( S_{25} = \dfrac{25}{2}(100 - 20) = 25 \times 40 = 1000 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13221, 'គេឱ្យស្វ៊ីត \( (a_n) \) មានតួទី \( n \) កំណត់ដោយ \( a_n = \dfrac{2n + 3}{4} \)។ តើស្វ៊ីតនេះជាស្វ៊ីតអ្វី?', NULL, '["ស្វ៊ីតនព្វន្តកើន ដែលមានផលសងរួម \\( d = \\dfrac{1}{2} \\)", "ស្វ៊ីតនព្វន្តចុះ ដែលមានផលសងរួម \\( d = -\\dfrac{1}{2} \\)", "ស្វ៊ីតនព្វន្តថេរ ដែលមានផលសងរួម \\( d = 0 \\)", "មិនមែនជាស្វ៊ីតនព្វន្ត"]', 0, NULL, 3, 'mcq', '\( a_{n+1} - a_n = \dfrac{2(n+1)+3}{4} - \dfrac{2n+3}{4} = \dfrac{2}{4} = \dfrac{1}{2} > 0 \) ថេរ។ ដូច្នេះជាស្វ៊ីតនព្វន្តកើន។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13222, 'សៀវភៅមួយក្បាលមាន \( 100 \) ទំព័រ (ចុះលេខពី \( 1 \) ដល់ \( 100 \))។ រកចំនួនទំព័រដែលមានលេខខាងចុងជាលេខ \( 5 \)៖', NULL, '["10 ទំព័រ", "9 ទំព័រ", "11 ទំព័រ", "12 ទំព័រ"]', 0, NULL, 3, 'mcq', 'ទំព័រទាំងនោះគឺ \( 5, 15, 25, 35, 45, 55, 65, 75, 85, 95 \) ដែលជាស្វ៊ីតនព្វន្ត \( a_1 = 5, d = 10 \) មាន \( n = 10 \) ទំព័រ។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13223, 'គេឱ្យ \( a_2 = -12 \) និងផលបូក \( S_{12} = 18 \) នៃស្វ៊ីតនព្វន្ត។ គណនាតម្លៃ \( a_6 \)៖', NULL, '["\\( -3 \\)", "\\( 0 \\)", "\\( 3 \\)", "\\( 6 \\)"]', 1, NULL, 3, 'mcq', '\( a_1 + d = -12 \) និង \( S_{12} = 6(2a_1 + 11d) = 18 \implies 2a_1 + 11d = 3 \)។ ដោះស្រាយប្រព័ន្ធបាន \( d = 3, a_1 = -15 \)។ នាំឱ្យ \( a_6 = a_1 + 5d = -15 + 15 = 0 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13224, 'គណនាផលបូក \( 5\dfrac{1}{4} + 4\dfrac{1}{2} + 3\dfrac{3}{4} + \dots + (-3) \)៖', NULL, '["\\( 12 \\)", "\\( 14.5 \\)", "\\( 15 \\)", "\\( 13.5 \\)"]', 3, NULL, 3, 'mcq', '\( a_1 = \dfrac{21}{4}, d = -\dfrac{3}{4} \)។ \( \dfrac{21}{4} - \dfrac{3}{4}(n - 1) = -3 \implies n = 12 \)។ \( S_{12} = \dfrac{12}{2}\left(\dfrac{21}{4} - 3\right) = 6 \times \dfrac{9}{4} = 13.5 \)។', 'ស្វ៊ីតនព្វន្ត', 'medium', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13225, 'គេមានស្វ៊ីតនព្វន្ត \( 51, 47, 43, \dots \)។ កំណត់តម្លៃ \( n \) ដែលធ្វើឱ្យផលបូក \( S_n \) មានតម្លៃអតិបរមា និងគណនាតម្លៃអតិបរមានោះ៖', NULL, '["\\( n = 12, \\, S_{12} = 348 \\)", "\\( n = 14, \\, S_{14} = 350 \\)", "\\( n = 13, \\, S_{13} = 364 \\)", "\\( n = 13, \\, S_{13} = 351 \\)"]', 3, NULL, 4, 'mcq', '\( a_n = 51 - 4(n - 1) = 55 - 4n > 0 \implies n < 13.75 \implies n = 13 \)។ \( S_{13} = \dfrac{13}{2}(51 + 3) = 351 \)។', 'ស្វ៊ីតនព្វន្ត', 'hard', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13226, 'ផលបូក \( 9 \) តួដំបូងនៃស្វ៊ីតនព្វន្តស្មើ \( 162 \) ហើយផលបូក \( 12 \) តួដំបូងស្មើ \( 288 \)។ គណនាផលបូក \( 30 \) តួដំបូង (\( S_{30} \))៖', NULL, '["\\( 1800 \\)", "\\( 1750 \\)", "\\( 1850 \\)", "\\( 1920 \\)"]', 0, NULL, 4, 'mcq', '\( S_9 = 9(a_1 + 4d) = 162 \implies a_1 + 4d = 18 \) និង \( S_{12} = 6(2a_1 + 11d) = 288 \implies 2a_1 + 11d = 48 \)។ រកបាន \( a_1 = 2, d = 4 \)។ នាំឱ្យ \( S_{30} = 15(4 + 116) = 1800 \)។', 'ស្វ៊ីតនព្វន្ត', 'hard', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13227, 'គេឱ្យស្វ៊ីតនព្វន្តពីរ ៖ \( 2, 7, 12, \dots \) និង \( 2, 5, 8, \dots \)។ ក្នុងចំណោម \( 121 \) តួដំបូងនៃស្វ៊ីតទាំងពីរ តើមានប៉ុន្មានតួដែលមានតម្លៃស្មើគ្នា?', NULL, '["24 តួ", "26 តួ", "25 តួ", "20 តួ"]', 2, NULL, 4, 'mcq', 'តួទី 121 នៃស្វ៊ីតទីពីរគឺ \( b_{121} = 2 + 120(3) = 362 \)។ តួដូចគ្នាចាប់ពី 2 និងមានផលសងរួម \( \text{LCM}(5, 3) = 15 \)។ \( 2 + 15(k - 1) \le 362 \implies 15(k - 1) \le 360 \implies k - 1 \le 24 \implies k = 25 \)។', 'ស្វ៊ីតនព្វន្ត', 'hard', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13228, 'បីចំនួនតគ្នាបង្កើតបានជាស្វ៊ីតនព្វន្តមួយ ដោយដឹងថាផលបូកបីចំនួននោះស្មើ \( 36 \) និងផលគុណស្មើ \( 1428 \)។ រកចំនួនទាំងបីនោះ៖', NULL, '["\\( 6, 12, 18 \\)", "\\( 7, 12, 17 \\)", "\\( 8, 12, 16 \\)", "\\( 5, 12, 19 \\)"]', 1, NULL, 4, 'mcq', 'តាង 3 ចំនួនដោយ \( x - d, x, x + d \)។ ផលបូក \( 3x = 36 \implies x = 12 \)។ ផលគុណ \( 12(144 - d^2) = 1428 \implies 144 - d^2 = 119 \implies d = 5 \)។ ចំនួនទាំងបីគឺ \( 7, 12, 17 \)។', 'ស្វ៊ីតនព្វន្ត', 'hard', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13229, 'ប្រាំចំនួនបង្កើតបានជាស្វ៊ីតនព្វន្តមួយ ដែលមានផលបូកស្មើ \( 125 \) ហើយផលបូកពីរតួដំបូងស្មើ \( 38 \)។ រកតូចុងក្រោយគេនៃស្វ៊ីតនោះ៖', NULL, '["\\( 31 \\)", "\\( 35 \\)", "\\( 33 \\)", "\\( 29 \\)"]', 2, NULL, 4, 'mcq', 'តាងតួទាំង 5 ដោយ \( x - 2d, x - d, x, x + d, x + 2d \)។ ផលបូក \( 5x = 125 \implies x = 25 \)។ ផលបូក 2 តួដំបូង \( (25 - 2d) + (25 - d) = 50 - 3d = 38 \implies d = 4 \)។ តួចុងក្រោយគឺ \( x + 2d = 25 + 8 = 33 \)។', 'ស្វ៊ីតនព្វន្ត', 'hard', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13230, 'គណនាផលបូកនៃស្វ៊ីត \( (-193) + (-189) + (-185) + \dots + (-17) \)៖', NULL, '["\\( -4725 \\)", "\\( -4620 \\)", "\\( -4830 \\)", "\\( -4500 \\)"]', 0, NULL, 4, 'mcq', '\( a_1 = -193, \, d = 4 \)។ \( -193 + 4(n - 1) = -17 \implies 4(n - 1) = 176 \implies n = 45 \)។ \( S_{45} = \dfrac{45}{2}(-193 - 17) = 45 \times (-105) = -4725 \)។', 'ស្វ៊ីតនព្វន្ត', 'hard', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13231, 'គេឱ្យស្វ៊ីតនព្វន្តមាន \( a_4 + a_8 = 34 \) និង \( a_6 + a_{10} = 46 \)។ រកផលសងរួម \( d \) និងតួទីមួយ \( a_1 \)៖', NULL, '["\\( d = 2, \\, a_1 = 5 \\)", "\\( d = 3, \\, a_1 = 2 \\)", "\\( d = 3, \\, a_1 = 4 \\)", "\\( d = 4, \\, a_1 = 1 \\)"]', 1, NULL, 4, 'mcq', '\( (a_6 + a_{10}) - (a_4 + a_8) = 4d = 46 - 34 = 12 \implies d = 3 \)។ \( 2a_1 + 10d = 34 \implies 2a_1 + 30 = 34 \implies a_1 = 2 \)។', 'ស្វ៊ីតនព្វន្ត', 'hard', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g11-cf76d56159.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13232, 'PISA សំណង់ទីធ្លាមុខផ្ទះ ៖ គេរៀបឥដ្ឋទីធ្លាមុខផ្ទះមួយរាងចតុកោណព្នាយមាន 18 ជួរ។ ជួរទី ១ មានឥដ្ឋ 14 ដុំ ហើយជួរបន្តបន្ទាប់មានចំនួនឥដ្ឋលើសជួរមុន 1 ដុំ រហូតដល់ជួរទី 18 មាន 31 ដុំ។ តើគេត្រូវចំណាយឥដ្ឋសរុបប៉ុន្មានដុំ?', 'g11-cf76d56159.svg', '["380 ដុំ", "405 ដុំ", "420 ដុំ", "450 ដុំ"]', 1, NULL, 5, 'mcq', 'ចំនួនឥដ្ឋជាស្វ៊ីតនព្វន្ត \( a_1 = 14, \, a_{18} = 31, \, n = 18 \)។ ផលបូកសរុប \( S_{18} = \dfrac{18}{2}(14 + 31) = 9 \times 45 = 405 \) ដុំ។', 'ស្វ៊ីតនព្វន្ត', 'pisa', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g11-774e74756b.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13233, 'PISA ប្លង់សាលប្រជុំ ៖ សាលប្រជុំមួយរៀបចំកៅអីជារាងចតុកោណព្នាយចំនួន 15 ជួរ។ ជួរមុខគេបង្អស់រៀបបាន 25 កៅអី, ជួរទី ២ រៀបបាន 27 កៅអី, ជួរទី ៣ រៀបបាន 29 កៅអី ហើយបន្តកើន 2 កៅអីរៀងរាល់ជួររហូតដល់ជួរក្រោយបង្អស់។ គណនាចំនួនកៅអីសរុបក្នុងសាលប្រជុំ៖', 'g11-774e74756b.svg', '["560 កៅអី", "600 កៅអី", "585 កៅអី", "575 កៅអី"]', 2, NULL, 5, 'mcq', '\( a_1 = 25, \, d = 2, \, n = 15 \)។ \( S_{15} = \dfrac{15}{2}[2(25) + 14(2)] = \dfrac{15}{2}[50 + 28] = 15 \times 39 = 585 \) កៅអី។', 'ស្វ៊ីតនព្វន្ត', 'pisa', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g11-f6542e3163.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13234, 'PISA ការប្រណាំងកង់ ៖ អ្នកជិះកង់ទី ១ ជិះបានចម្ងាយ 15 km ក្នុង 1 ថ្ងៃ។ ប្រាំបីថ្ងៃក្រោយមក ទើបអ្នកជិះកង់ទី ២ ចាប់ផ្តើមចេញដំណើរតាមផ្លូវដដែល ដោយថ្ងៃទី ១ ជិះបាន 14 km ហើយថ្ងៃបន្ទាប់ៗកើន 2 km ក្នុង 1 ថ្ងៃរៀងរាល់ថ្ងៃ។ តើអ្នកជិះកង់ទី ២ ត្រូវចំណាយពេលប៉ុន្មានថ្ងៃដើម្បីជិះទាន់អ្នកទី ១?', 'g11-f6542e3163.svg', '["12 ថ្ងៃ", "10 ថ្ងៃ", "14 ថ្ងៃ", "15 ថ្ងៃ"]', 0, NULL, 5, 'mcq', 'តាង \( n \) ជាចំនួនថ្ងៃរបស់អ្នកទី ២។ ចម្ងាយអ្នកទី ១ ៖ \( D_1 = 15(n + 8) \)។ ចម្ងាយអ្នកទី ២ ៖ \( D_2 = \dfrac{n}{2}[28 + 2(n - 1)] = n(n + 13) \)។ សមីការ \( n^2 + 13n = 15n + 120 \implies n^2 - 2n - 120 = 0 \implies (n - 12)(n + 10) = 0 \implies n = 12 \) ថ្ងៃ។', 'ស្វ៊ីតនព្វន្ត', 'pisa', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13235, 'PISA ប្រាក់បៀវត្សប្រចាំឆ្នាំ ៖ តំណាងក្រុមហ៊ុនម្នាក់ទទួលប្រាក់បៀវត្សក្នុងឆ្នាំទី ១ គឺ 30 លានរៀល និងក្នុងឆ្នាំទី ៧ គឺ 60 លានរៀល។ ដោយដឹងថាប្រាក់បៀវត្សកើនឡើងជាស្វ៊ីតនព្វន្ត តើក្នុងឆ្នាំទី ១០ គាត់ទទួលបានប្រាក់បៀវត្សប៉ុន្មាន?', NULL, '["70 លានរៀល", "75 លានរៀល", "80 លានរៀល", "85 លានរៀល"]', 1, NULL, 5, 'mcq', '\( a_7 = a_1 + 6d \implies 60 = 30 + 6d \implies d = 5 \) លានរៀល/ឆ្នាំ។ ឆ្នាំទី ១០ ៖ \( a_{10} = a_7 + 3d = 60 + 3(5) = 75 \) លានរៀល។', 'ស្វ៊ីតនព្វន្ត', 'pisa', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13236, 'PISA ជម្រើសការងាររដូវក្តៅ (រយៈពេល 3 ខែ ឬ 12 សប្តាហ៍) ៖ ការងារ A ផ្តល់ប្រាក់ខែ 400,000 រៀល/ខែ និងដំឡើង 100,000 រៀលរាល់ខែ។ ការងារ B ផ្តល់ 100,000 រៀល/សប្តាហ៍ និងដំឡើង 5,000 រៀលរាល់សប្តាហ៍។ តើការងារណាផ្តល់ប្រាក់ចំណូលសរុបច្រើនជាង និងច្រើនជាងប៉ុន្មាន?', NULL, '["ការងារ A ច្រើនជាងការងារ B ចំនួន 30,000 រៀល", "ការងារ B ច្រើនជាងការងារ A ចំនួន 30,000 រៀល", "ការងារទាំងពីរទទួលបានប្រាក់ស្មើគ្នា", "ការងារ B ច្រើនជាងការងារ A ចំនួន 50,000 រៀល"]', 1, NULL, 5, 'mcq', 'ការងារ A: \( 400\,000 + 500\,000 + 600\,000 = 1\,500\,000 \) រៀល។ ការងារ B: \( S_{12} = \dfrac{12}{2}[2(100\,000) + 11(5\,000)] = 6(255\,000) = 1\,530\,000 \) រៀល។ ដូច្នេះ B ច្រើនជាង A ចំនួន \( 30\,000 \) រៀល។', 'ស្វ៊ីតនព្វន្ត', 'pisa', 1, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13237, 'គេមានស្វ៊ីតនព្វន្ត \( 7, 12, 17, 22, 27, \dots \)។
ក. កំណត់ផលសងរួម \( d \) នៃស្វ៊ីត។
ខ. សរសេររូបមន្តតួទី \( n \) នៃស្វ៊ីត។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផលសងរួម d = a_2 - a_1 = 12 - 7 = 5 (2 ពិន្ទុ)
សរសេររូបមន្តទូទៅ a_n = a_1 + (n - 1)d = 7 + 5(n - 1) (1.5 ពិន្ទុ)
សម្រួលកន្សោម a_n = 5n + 2 (1.5 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'easy', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13238, 'គេមានស្វ៊ីតនព្វន្ត \( -8, -3, 2, 7, \dots \)។
ក. គណនាតួទី \( 17 \) (\( a_{17} \)) និងតួទី \( 43 \) (\( a_{43} \))។
ខ. តើតួទីប៉ុន្មាននៃស្វ៊ីតស្មើនឹង \( 322 \)?', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ a_1 = -8 និងផលសងរួម d = -3 - (-8) = 5 (1 ពិន្ទុ)
គណនា a_17 = -8 + 16(5) = 72 (1 ពិន្ទុ)
គណនា a_43 = -8 + 42(5) = 202 (1 ពិន្ទុ)
បង្កើតសមីការ -8 + 5(n - 1) = 322 (1 ពិន្ទុ)
ដោះស្រាយបាន 5(n - 1) = 330 => n = 67 (ជាតួទី 67) (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'medium', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13239, 'គណនាផលបូកនៃកន្សោមស្វ៊ីតនព្វន្ត ៖ \( S = 3 + 7 + 11 + 15 + \dots + 99 \)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់តួទីមួយ a_1 = 3 និងផលសងរួម d = 4 (1 ពិន្ទុ)
ស្វែងរកចំនួនតួ n តាមសមីការ 3 + 4(n - 1) = 99 (1.5 ពិន្ទុ)
ដោះស្រាយបាន 4(n - 1) = 96 => n = 25 តួ (1 ពិន្ទុ)
អនុវត្តរូបមន្តផលបូក S_25 = (25 / 2) * (3 + 99) (1 ពិន្ទុ)
គណនាលទ្ធផលចុងក្រោយ S_25 = 25 * 51 = 1275 (0.5 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'medium', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13240, 'គេឱ្យស្វ៊ីតនព្វន្តមួយមានតួទី ៥ ស្មើនឹង \( 19 \) និងតួទី ១១ ស្មើនឹង \( 43 \)។
ក. រកតួទីមួយ \( a_1 \) និងផលសងរួម \( d \)។
ខ. គណនាផលបូក ២០ តួដំបូង \( S_{20} \)។', NULL, '[]', 0, NULL, 5, 'writing', 'បង្កើតប្រព័ន្ធសមីការ a_1 + 4d = 19 និង a_1 + 10d = 43 (1.5 ពិន្ទុ)
ដកសមីការទាំងពីររកបាន 6d = 24 => d = 4 (1 ពិន្ទុ)
ជំនួសរកបាន a_1 = 19 - 16 = 3 (0.5 ពិន្ទុ)
សរសេររូបមន្តផលបូក S_20 = (20 / 2) * [2(3) + 19(4)] (1 ពិន្ទុ)
គណនាលទ្ធផល S_20 = 10 * (6 + 76) = 820 (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'medium', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13241, 'បង្ហាញថាស្វ៊ីត \( (a_n) \) ដែលមានតួទី \( n \) កំណត់ដោយ \( a_n = \dfrac{2n + 3}{4} \) ជាស្វ៊ីតនព្វន្តកើន។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរកន្សោមតួទី n+1 : a_{n+1} = [2(n + 1) + 3] / 4 = (2n + 5) / 4 (1.5 ពិន្ទុ)
គណនាផលសង a_{n+1} - a_n = (2n + 5)/4 - (2n + 3)/4 (1.5 ពិន្ទុ)
សម្រួលផលសងបាន 2/4 = 1/2 (1 ពិន្ទុ)
សន្និដ្ឋានថា ដោយ a_{n+1} - a_n = 1/2 ជាចំនួនថេរ និងវិជ្ជមាន នោះ (a_n) ជាស្វ៊ីតនព្វន្តកើន (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'medium', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13242, 'ស្វ៊ីតនព្វន្តមួយមានផលបូក ៩ តួដំបូងស្មើនឹង \( 162 \) ហើយផលបូក ១២ តួដំបូងស្មើនឹង \( 288 \)។
ក. កំណត់តួទីមួយ \( a_1 \) និងផលសងរួម \( d \) នៃស្វ៊ីត។
ខ. គណនាផលបូក ៣០ តួដំបូង \( S_{30} \)។', NULL, '[]', 0, NULL, 5, 'writing', 'សរសេរសមីការ S_9 = (9/2)(2a_1 + 8d) = 9(a_1 + 4d) = 162 => a_1 + 4d = 18 (1.5 ពិន្ទុ)
សរសេរសមីការ S_12 = (12/2)(2a_1 + 11d) = 6(2a_1 + 11d) = 288 => 2a_1 + 11d = 48 (1.5 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធសមីការបាន d = 4 និង a_1 = 2 (1 ពិន្ទុ)
គណនា S_30 = (30/2)[2(2) + 29(4)] = 15(4 + 116) = 15 * 120 = 1800 (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'hard', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13243, 'បីចំនួនតគ្នាបង្កើតបានជាស្វ៊ីតនព្វន្តមួយ។ គេដឹងថាផលបូកនៃបីចំនួននេះស្មើនឹង \( 36 \) និងផលគុណរបស់វាស្មើនឹង \( 1428 \)។ ចូរស្វែងរកចំនួនទាំងបីនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាងបីចំនួនជាស្វ៊ីតនព្វន្តដោយ x - d, x, x + d (1 ពិន្ទុ)
ផលបូក (x - d) + x + (x + d) = 3x = 36 => x = 12 (1 ពិន្ទុ)
ផលគុណ (12 - d)(12)(12 + d) = 1428 => 144 - d^2 = 119 (1.5 ពិន្ទុ)
ទាញបាន d^2 = 25 => d = 5 ឬ d = -5 (0.5 ពិន្ទុ)
សន្និដ្ឋានចំនួនទាំងបីនោះគឺ 7, 12, 17 (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'hard', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13244, 'ប្រាំចំនួនបង្កើតបានជាស្វ៊ីតនព្វន្តមួយ ដែលមានផលបូកស្មើនឹង \( 125 \) ហើយផលបូកពីរតួដំបូងស្មើនឹង \( 38 \)។
ក. កំណត់ផលសងរួម \( d \) និងតួទីមួយ \( a_1 \)។
ខ. សរសេរប្រាំចំនួននោះចេញមក។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង 5 ចំនួនដោយ x - 2d, x - d, x, x + d, x + 2d => ផលបូក 5x = 125 => x = 25 (1.5 ពិន្ទុ)
ផលបូកពីរតួដំបូង (x - 2d) + (x - d) = 2x - 3d = 50 - 3d = 38 (1.5 ពិន្ទុ)
ដោះស្រាយបាន 3d = 12 => d = 4 (1 ពិន្ទុ)
គណនាតួទីមួយ a_1 = 25 - 2(4) = 17 និង 5 ចំនួនគឺ 17, 21, 25, 29, 33 (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'hard', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13245, 'គេឱ្យស្វ៊ីតនព្វន្តពីរ ៖ \( A = (2, 7, 12, \dots) \) និង \( B = (2, 5, 8, \dots) \)។
ចូររកចំនួនតួដែលមានតម្លៃស្មើគ្នាក្នុងចំណោម \( 121 \) តួដំបូងនៃស្វ៊ីតទាំងពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់តួទី 121 នៃស្វ៊ីត A : a_{121} = 2 + 120(5) = 602 (1 ពិន្ទុ)
កំណត់តួទី 121 នៃស្វ៊ីត B : b_{121} = 2 + 120(3) = 362 (1 ពិន្ទុ)
កំណត់តួដូចគ្នាបង្កើតបានជាស្វ៊ីតនព្វន្ត C មាន c_1 = 2 និងផលសងរួម LCM(5,3) = 15 (1 ពិន្ទុ)
កំណត់លក្ខខណ្ឌតួចុងក្រោយ c_k <= min(602, 362) = 362 (1 ពិន្ទុ)
ដោះស្រាយ 2 + 15(k - 1) <= 362 => 15(k - 1) <= 360 => k - 1 <= 24 => k = 25 តួ (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'hard', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13246, 'PISA សំណង់ទីធ្លាមុខផ្ទះ ៖ ម្ចាស់ផ្ទះម្នាក់រៀបចំក្រាលឥដ្ឋទីធ្លាមុខផ្ទះរាងចតុកោណព្នាយមួយដែលមាន ១៨ ជួរ។
ជួរទី ១ ប្រើប្រាស់ឥដ្ឋ ១៤ ដុំ ហើយជួរបន្តបន្ទាប់នីមួយៗប្រើឥដ្ឋលើសជួរមុន ១ ដុំ រហូតដល់ជួរទី ១៨ ប្រើអស់ ៣១ ដុំ។
ក. បង្ហាញថាចំនួនឥដ្ឋតាមជួរនីមួយៗបង្កើតបានជាស្វ៊ីតនព្វន្តមួយ ដោយបញ្ជាក់តួទីមួយ និងផលសងរួម។
ខ. គណនាចំនួនដុំឥដ្ឋសរុបដែលត្រូវចំណាយដើម្បីក្រាលទីធ្លានេះ។', 'g11-cf76d56159.svg', '[]', 0, NULL, 5, 'writing', 'ពន្យល់ថាចំនួនឥដ្ឋកើន 1 ដុំថេរតាមជួរ ដូច្នេះជាស្វ៊ីតនព្វន្តដែលមាន a_1 = 14 និង d = 1 (1.5 ពិន្ទុ)
ផ្ទៀងផ្ទាត់តួទី 18 : a_18 = 14 + (18 - 1)*1 = 14 + 17 = 31 (ត្រឹមត្រូវ) (1 ពិន្ទុ)
សរសេររូបមន្តផលបូក S_18 = (18 / 2) * (a_1 + a_18) (1 ពិន្ទុ)
ជំនួសលេខ S_18 = 9 * (14 + 31) = 9 * 45 = 405 ដុំ (1.5 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'pisa', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13247, 'PISA ស្ថាបត្យកម្មសាលប្រជុំ ៖ សាលប្រជុំមួយត្រូវបានសាងសង់ដោយរៀបកៅអីជារាងចតុកោណព្នាយចំនួន ១៥ ជួរ។
ជួរមុខគេបង្អស់មាន ២៥ កៅអី, ជួរទី ២ មាន ២៧ កៅអី, ជួរទី ៣ មាន ២៩ កៅអី ហើយកើនឡើង ២ កៅអីរៀងរាល់ជួររហូតដល់ជួរទី ១៥។
ក. គណនាចំនួនកៅអីនៅក្នុងជួរក្រោយបង្អស់ (ជួរទី ១៥)។
ខ. គណនាចំនួនកៅអីអង្គុយសរុបទាំងអស់ដែលមាននៅក្នុងសាលប្រជុំនោះ។', 'g11-774e74756b.svg', '[]', 0, NULL, 5, 'writing', 'កំណត់ស្វ៊ីតនព្វន្ត a_1 = 25, d = 2, n = 15 (1 ពិន្ទុ)
គណនាកៅអីជួរទី 15 : a_15 = a_1 + 14d = 25 + 14(2) = 25 + 28 = 53 កៅអី (2 ពិន្ទុ)
សរសេររូបមន្តផលបូកសរុប S_15 = (15 / 2) * (25 + 53) = (15 / 2) * 78 (1 ពិន្ទុ)
គណនាលទ្ធផលចុងក្រោយ S_15 = 15 * 39 = 585 កៅអី (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'pisa', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13248, 'PISA ការធ្វើដំណើរតាមទាន់គ្នា ៖ អ្នកជិះកង់ម្នាក់ជិះបានចម្ងាយ 15 km ក្នុងមួយថ្ងៃ។ ប្រាំបីថ្ងៃក្រោយមក ទើបអ្នកជិះកង់ទីពីរចាប់ផ្តើមចេញដំណើរតាមផ្លូវដដែល ដោយថ្ងៃទីមួយគាត់ជិះបានចម្ងាយ 14 km ហើយថ្ងៃបន្ទាប់ៗមកទៀត គាត់ត្រូវជិះកើន ២ km ក្នុងមួយថ្ងៃជារៀងរាល់ថ្ងៃដើម្បីឱ្យទាន់អ្នកជិះកង់ទីមួយ។
តើអ្នកជិះកង់ទីពីរត្រូវចំណាយពេលប៉ុន្មានថ្ងៃដើម្បីជិះទៅទាន់អ្នកជិះកង់ទីមួយ? ចូរគណនាចម្ងាយដែលអ្នកទាំងពីរជិះបាននៅពេលជួបគ្នា។', 'g11-f6542e3163.svg', '[]', 0, NULL, 5, 'writing', 'តាង n ជាចំនួនថ្ងៃរបស់អ្នកជិះកង់ទីពីរ (n > 0) (0.5 ពិន្ទុ)
សរសេរចម្ងាយសរុបរបស់អ្នកទីមួយ D_1 = 15 * (n + 8) = 15n + 120 (1 ពិន្ទុ)
សរសេរចម្ងាយសរុបរបស់អ្នកទីពីរ D_2 = (n / 2) * [2(14) + (n - 1)*2] = n(n + 13) = n^2 + 13n (1.5 ពិន្ទុ)
បង្កើតសមីការជួបគ្នា D_2 = D_1 <=> n^2 - 2n - 120 = 0 (1 ពិន្ទុ)
ដោះស្រាយសមីការដឺក្រេទីពីរ (n - 12)(n + 10) = 0 => n = 12 ថ្ងៃ (0.5 ពិន្ទុ)
គណនាចម្ងាយជួបគ្នា D = 15 * (12 + 8) = 300 km (0.5 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'pisa', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13249, 'PISA ផែនការហិរញ្ញវត្ថុ ៖ តំណាងក្រុមហ៊ុនធានារ៉ាប់រងម្នាក់ទទួលបានប្រាក់បៀវត្សក្នុងឆ្នាំទី ១ ចំនួន ៣០ លានរៀល និងក្នុងឆ្នាំទី ៧ ចំនួន ៦០ លានរៀល។ គេដឹងថាប្រាក់បៀវត្សប្រចាំឆ្នាំរបស់គាត់កើនឡើងតាមលំដាប់នៃស្វ៊ីតនព្វន្ត។
ក. រកចំនួនប្រាក់ដែលត្រូវបានដំឡើងជារៀងរាល់ឆ្នាំ (ផលសងរួម d)។
ខ. គណនាប្រាក់បៀវត្សរបស់គាត់ក្នុងឆ្នាំទី ១០។
គ. គណនាប្រាក់ចំណូលសរុបដែលគាត់ទទួលបានក្នុងរយៈពេល ១០ ឆ្នាំដំបូង។', NULL, '[]', 0, NULL, 5, 'writing', 'បង្កើតសមីការ a_7 = a_1 + 6d => 60 = 30 + 6d => d = 5 លានរៀល/ឆ្នាំ (1.5 ពិន្ទុ)
គណនាប្រាក់បៀវត្សឆ្នាំទី 10 : a_10 = 30 + 9(5) = 75 លានរៀល (1.5 ពិន្ទុ)
សរសេររូបមន្តផលបូក 10 ឆ្នាំ S_10 = (10 / 2) * (a_1 + a_10) (1 ពិន្ទុ)
គណនា S_10 = 5 * (30 + 75) = 5 * 105 = 525 លានរៀល (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'pisa', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 13250, 'PISA ការស្រាវជ្រាវបម្រែបម្រួលសីតុណ្ហភាព ៖ ក្នុងការពិសោធន៍មួយ គេសង្កេតឃើញសីតុណ្ហភាពនៃអង្គធាតុរាវមួយថយចុះជាស្វ៊ីតនព្វន្ត។ នៅនាទីទី ៣ សីតុណ្ហភាពគឺ 54°C ហើយនៅនាទីទី ៨ សីតុណ្ហភាពធ្លាក់ចុះមកនៅត្រឹម 39°C។
ក. កំណត់អត្រានៃការធ្លាក់ចុះសីតុណ្ហភាពក្នុងមួយនាទី (ផលសងរួម d)។
ខ. តើសីតុណ្ហភាពដំបូងនៅនាទីទី ១ ស្មើនឹងប៉ុន្មាន?
គ. តើនៅនាទីទីប៉ុន្មាន ទើបសីតុណ្ហភាពធ្លាក់ចុះដល់ 0°C?', NULL, '[]', 0, NULL, 5, 'writing', 'បង្កើតសមីការ a_8 - a_3 = 5d = 39 - 54 = -15 => d = -3 °C/នាទី (ថយចុះ 3°C ក្នុង 1 នាទី) (1.5 ពិន្ទុ)
គណនាសីតុណ្ហភាពនាទីទី 1 : a_1 = a_3 - 2d = 54 - 2(-3) = 60°C (1.5 ពិន្ទុ)
បង្កើតសមីការ a_n = 60 - 3(n - 1) = 0 (1 ពិន្ទុ)
ដោះស្រាយ 3(n - 1) = 60 => n - 1 = 20 => n = 21 (នៅនាទីទី 21) (1 ពិន្ទុ)', 'ស្វ៊ីតនព្វន្ត', 'pisa', 0, '11SC', 'ស្វ៊ីតនព្វន្ត', 'ជំពូកទី 1 : ស្វ៊ីតនិងអនុមានរួមគណិតវិទ្យា', NULL, 0);
